fn shell_game(n: i32, x: i8) -> i8 {
    // Because the moves repeat with period 6 and f(6, x) = x for all x in {0,1,2},
    // we only need to simulate n % 6 steps.
    let mut pos = x;
    let r = n % 6;
    for step in 1..=r {
        if step % 2 != 0 {
            // Odd step: swap positions 0 and 1
            match pos {
                0 => pos = 1,
                1 => pos = 0,
                _ => {}
            }
        } else {
            // Even step: swap positions 1 and 2
            match pos {
                1 => pos = 2,
                2 => pos = 1,
                _ => {}
            }
        }
    }
    pos
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_shell_game_small() {
        // Starting at 0
        assert_eq!(shell_game(1, 0), 1);
        assert_eq!(shell_game(2, 0), 2);
        assert_eq!(shell_game(3, 0), 2);
        assert_eq!(shell_game(4, 0), 1);
        assert_eq!(shell_game(5, 0), 0);
        assert_eq!(shell_game(6, 0), 0);
        assert_eq!(shell_game(7, 0), 1);

        // Starting at 1
        assert_eq!(shell_game(1, 1), 0);
        assert_eq!(shell_game(2, 1), 0);
        assert_eq!(shell_game(3, 1), 1);
        assert_eq!(shell_game(4, 1), 2);
        assert_eq!(shell_game(5, 1), 2);
        assert_eq!(shell_game(6, 1), 1);

        // Starting at 2
        assert_eq!(shell_game(1, 2), 2);
        assert_eq!(shell_game(2, 2), 1);
        assert_eq!(shell_game(3, 2), 0);
        assert_eq!(shell_game(4, 2), 0);
        assert_eq!(shell_game(5, 2), 1);
        assert_eq!(shell_game(6, 2), 2);
    }

    #[test]
    fn test_shell_game_large() {
        // For multiples of 6, the position returns to the start.
        for x in 0..3 {
            assert_eq!(shell_game(6_000_000_000i32 % 6, x), x);
            assert_eq!(shell_game(6_000_000_006, x), x);
        }
        // Random checks
        assert_eq!(shell_game(10, 0), 1);
        assert_eq!(shell_game(10, 1), 1);
        assert_eq!(shell_game(10, 2), 1);
    }
}